import json, itertools, math
from pathlib import Path
slug='what_is_net_income_loss_for_the_most_recent_fiscal_year_10_llm'
base=Path('results/financebench/lsf/single_cluster/llm/gpt54/one_shot')
# D* from eval_merge
merge=json.loads((base/'eval_merge'/'what_is_net_income_loss_for_the_most_recent_fiscal_year_10_sampled.json').read_text())
Dstar={d['doc_name'] for d in merge['per_doc'] if d['correct']}
# costs
costs=json.loads((base/'cost_profile'/f'{slug}.json').read_text())
# coverage cache per rule
cov={}
correct_docs={}
for p in (base/'eval_individual'/slug).glob('rule_*_eval.json'):
    j=json.loads(p.read_text())
    r=j['rule_name']
    cov[r]=sum(1 for d in j['per_document'] if d['correct'])/len(j['per_document'])
    correct_docs[r]={d['doc_name'] for d in j['per_document'] if d['correct']}
# cost profile format maybe list or dict
if isinstance(costs, dict) and slug in costs:
    costs=costs[slug]
if isinstance(costs, dict) and 'per_rule' in costs:
    cost_map=costs['per_rule']
else:
    cost_map={k:v['avg_cost_ratio'] if isinstance(v,dict) else v for k,v in costs.items()}
# normalize
for k,v in list(cost_map.items()):
    if isinstance(v,dict):
        cost_map[k]=v.get('avg_cost_ratio')
rows=[]
rules=sorted(cost_map)
for r in rules:
    rows.append((cost_map[r], -cov.get(r,0), r, correct_docs.get(r,set())))
# print top by cov/cost ratio and all exact cover subsets up to size 4
print('D*',sorted(Dstar), 'size', len(Dstar))
print('\\nTop by cov/cost:')
for r in sorted(rules, key=lambda r: (-(cov.get(r,0)/(cost_map[r] or 1e-9) if cost_map[r] is not None else -1), cost_map[r]))[:15]:
    c=cost_map[r]
    cv=cov.get(r,0)
    print(f'{r} cost={c:.6f} cov={cv:.1f} ratio={cv/c if c else math.inf:.1f} docs={sorted(correct_docs[r])}')

best=[]
for k in range(1,5):
    for combo in itertools.combinations(rules,k):
        covered=set().union(*(correct_docs.get(r,set()) for r in combo))
        if Dstar <= covered:
            sc=sum(cost_map[r] for r in combo)
            mincov=min(cov.get(r,0) for r in combo)
            meancov=sum(cov.get(r,0) for r in combo)/len(combo)
            best.append((sc, -mincov, k, combo, meancov))
    if best:
        break
print('\\nExact-cover subsets at smallest k:')
for sc, negmincov, k, combo, meancov in sorted(best)[:20]:
    print(f'k={k} cost={sc:.6f} mincov={-negmincov:.1f} meancov={meancov:.3f} combo={combo}')

# best by cost regardless of k up to 4
